local function apply(r,id)
    local fix=fixes[id];if not fix then return end
    for k,v in pairs(fix) do r[k]=v end
    if fix.learn and r.source then
        r.source=r.source:gsub("learn at %d+","learn at "..fix.learn)
    end
    for _,ref in ipairs(acquisition[id] or {}) do
        r.acquisitionItems=r.acquisitionItems or {};local exists=false
        for _,old in ipairs(r.acquisitionItems) do if old.id==ref.id then exists=true end end
        if not exists then r.acquisitionItems[#r.acquisitionItems+1]={id=ref.id} end
    end
end
for id,item in pairs(items) do
    local meta=P.ItemMeta[id] or {};P.ItemMeta[id]=meta
    meta.name=meta.name or item.name;meta.url=meta.url or item.url
    meta.sources=meta.sources or {}
end
for _,collection in ipairs({P.Catalog or {},P.Recipes or {}}) do
    for _,rows in pairs(collection) do for _,r in ipairs(rows) do apply(r,r.spell) end end
end
for id in pairs(fixes) do if P.SpellMeta[id] then apply(P.SpellMeta[id],id) end end
for _,rows in pairs(P.MaterialCrafts or {}) do for _,r in ipairs(rows) do
    local f=fixes[r.spell];if f and f.learn then r.learn=f.learn end
end end
for key,rows in pairs(P.GatherMaterialUses or {}) do
    local changed,first,last=false,nil,nil
    for _,r in ipairs(rows) do
        local f=fixes[r.spell];if f and f.learn then r.learn=f.learn;changed=true end
        if r.learn then first=math.min(first or r.learn,r.learn);last=math.max(last or r.learn,r.learn) end
    end
    local range=P.MaterialSkillRanges and P.MaterialSkillRanges[key]
    if changed and first and range and not range.indirect then range.first=first;range.last=last end
end
